package io.github.jesterportfolio.hearth.verification;
import java.util.*;import java.util.concurrent.*;import java.nio.file.*;import org.bukkit.Bukkit;
import io.github.jesterportfolio.hearth.economy.*;import io.github.jesterportfolio.hearth.survival.platform.*;
public final class PlatformOperationsVerification {
 private static void check(PlatformRuntime p,boolean ok,String name){if(!ok)throw new IllegalStateException(name);p.plugin.getLogger().info("HEARTH_OPERATIONS_CHECK PASS "+name);}
 private static CompletionStage<Void> reject(PlatformRuntime p,CompletionStage<?> work,String name){return work.handleAsync((v,e)->{check(p,e!=null,name);return (Void)null;},p.owner);}
 public static CompletionStage<Void> run(PlatformRuntime p,String phase){try{
  var root=IsolatedPaths.require(Path.of(System.getProperty("hearth.aura.verification.root","")),"hearth-native-economy-run.");if(!Files.readString(root.resolve(".hearth-aura-isolated")).equals("Hearth AuraSkills isolated v1\n")||!Path.of("").toRealPath().equals(root.resolve("server"))||!Bukkit.getOnlineMode()||!Bukkit.hasWhitelist()||!Bukkit.getIp().equals("127.0.0.1")||!Bukkit.getOnlinePlayers().isEmpty()||!Set.of("prepare","resume","ready").contains(phase))throw new IllegalStateException("OPERATIONS_FIXTURE_GATE");Files.writeString(root.resolve("operations-"+phase+".started"),"owned zero Players\n",StandardOpenOption.CREATE_NEW);var values=new Properties();Path expected=root.resolve("operations-expected.properties");
  if(phase.equals("ready")){try(var in=Files.newBufferedReader(expected)){values.load(in);}UUID id=UUID.fromString(values.getProperty("world")),config=UUID.fromString(values.getProperty("config"));check(p,p.ready()&&p.jobsAllowed()&&p.configReview().clear(),"final_JAR_restores_ready_with_archived_history");Path level=Bukkit.getServer().getLevelDirectory();return p.archives.vault(id).thenCompose(row->p.files.submit(()->new ResourceVault(level).seal(new ResourceVault(level).source(row.orElseThrow().key())))).thenAcceptAsync(seal->check(p,seal.equals(values.getProperty("world-seal")),"final_bounded_traversal_keeps_restored_world_seal_unchanged"),p.owner).thenCompose(v->p.inspectConfig(config)).thenAcceptAsync(d->check(p,p.changes.archived(d.plan())&&d.plan().after().equals(values.getProperty("config-hash")),"final_JAR_reads_same_cold_configuration_identity"),p.owner).thenComposeAsync(v->reject(p,p.apply(config,false),"archived_apply_is_a_harmless_preflight_refusal"),p.owner).thenRunAsync(()->check(p,p.ready()&&!p.maintenance(),"invalid_archived_request_does_not_close_a_healthy_platform"),p.owner).thenComposeAsync(v->barrier(p),p.owner).thenComposeAsync(v->preserved(p,values),p.owner);}
  if(phase.equals("resume")){try(var in=Files.newBufferedReader(expected)){values.load(in);}UUID id=UUID.fromString(values.getProperty("world")),config=UUID.fromString(values.getProperty("config"));check(p,p.maintenance()&&!p.jobsAllowed()&&p.diagnostics().get("vault_held")==1,"new_JVM_preserves_unconfirmed_world_restore_and_blocks_dispatch");return reject(p,p.recoverConfig(),"generic_configuration_recovery_cannot_clear_world_restore")
    .thenComposeAsync(v->p.vaultResource(id,true),p.owner).thenRunAsync(()->check(p,p.ready()&&p.jobsAllowed(),"same_world_restore_request_finishes_without_recreating_world"),p.owner)
    .thenCompose(v->p.inspectConfig(config)).thenAcceptAsync(detail->check(p,p.changes.archived(detail.plan())&&detail.plan().after().equals(values.getProperty("config-hash")),"new_JVM_reads_archived_candidate_and_immutable_hash"),p.owner)
    .thenComposeAsync(v->reject(p,p.apply(config,false),"archived_configuration_cannot_be_reapplied"),p.owner).thenComposeAsync(v->p.recoverConfig(),p.owner)
    .thenCompose(v->p.archives.vault(id)).thenAcceptAsync(row->check(p,row.orElseThrow().state().equals("RESTORED")&&p.ready(),"restore_receipt_and_configuration_recovery_are_independent"),p.owner)
    .thenComposeAsync(v->preserved(p,values),p.owner);
  }
  check(p,p.ready()&&p.configReview().clear(),"existing_platform_boots_with_E014_without_content_changes");try(var in=Files.newBufferedReader(root.resolve("jobs-expected.properties"))){values.load(in);}
  Path data=p.plugin.getDataFolder().toPath();return p.files.submit(()->{var props=new Properties();try(var in=Files.newBufferedReader(data.resolve("platform.properties"))){props.load(in);}props.setProperty("stats.cap","124");try(var out=Files.newBufferedWriter(data.resolve("operations_trial.candidate"),StandardOpenOption.CREATE_NEW)){props.store(out,"owned platform operations fixture only");}return (Void)null;})
    .thenCompose(v->p.stageConfig("platform.properties","operations_trial.candidate"))
    .thenComposeAsync(plan->{values.setProperty("config",plan.id().toString());values.setProperty("config-hash",plan.after());return p.apply(plan.id(),false).thenComposeAsync(v->p.archiveConfig(plan.id()),p.owner).thenCompose(v->p.inspectConfig(plan.id())).thenAcceptAsync(detail->check(p,p.changes.archived(detail.plan())&&p.ready()&&p.settings().statCap()==124,"async_apply_and_config_archive_keep_live_settings_and_READINESS"),p.owner);},p.owner)
    .thenComposeAsync(v->p.store.resets(),p.owner).thenComposeAsync(rows->{var retired=rows.stream().filter(r->r.phase().equals("RETIRED")&&r.world()!=null&&r.key().startsWith("hearth_resource:")&&Bukkit.getWorld(r.world())==null&&rows.stream().noneMatch(a->Set.of("ACTIVE","PREPARING","READY").contains(a.phase())&&(r.world().equals(a.world())||r.world().equals(a.oldWorld())))).findFirst().orElseThrow();values.setProperty("world",retired.request().toString());values.setProperty("world-uuid",retired.world().toString());return p.vaultResource(retired.request(),false);},p.owner)
    .thenCompose(v->p.archives.vault(UUID.fromString(values.getProperty("world")))).thenComposeAsync(found->{var row=found.orElseThrow();check(p,row.state().equals("STORED")&&Bukkit.getWorld(row.world())==null&&p.ready(),"actual_unloaded_retired_world_is_sealed_and_moved_to_cold_store");values.setProperty("world-seal",row.seal());Path level=Bukkit.getServer().getLevelDirectory();return p.archives.transition(row,"RESTORING").thenCompose(v->p.files.submit(()->{new ResourceVault(level).move(row.key(),row.id(),row.seal(),true);return (Void)null;}));},p.owner)
    .thenComposeAsync(v->reject(p,p.recoverConfig(),"unconfirmed_restore_remains_held_after_files_have_moved"),p.owner)
    .thenComposeAsync(v->readLoad(p),p.owner).thenComposeAsync(v->preserved(p,values),p.owner).thenRunAsync(()->{try(var out=Files.newBufferedWriter(expected,StandardOpenOption.CREATE_NEW)){values.store(out,"owned operations restoration");}catch(Exception e){throw new CompletionException(e);}},p.owner);
 }catch(Exception e){return CompletableFuture.failedFuture(e);}}
 private static CompletionStage<Void> barrier(PlatformRuntime p){Path data=p.plugin.getDataFolder().toPath();return p.files.submit(()->{Files.writeString(data.resolve("operations_barrier.candidate"),Files.readString(data.resolve("platform.properties"))+"\n# configuration admission barrier fixture\n",StandardOpenOption.CREATE_NEW);return (Void)null;}).thenCompose(v->p.stageConfig("platform.properties","operations_barrier.candidate")).thenComposeAsync(plan->{var work=p.apply(plan.id(),false);check(p,!p.rpg.runtime.platformTransactionsAllowed()&&!p.jobsAllowed(),"live_configuration_blocks_shared_economy_and_RPG_admission");return work.thenRunAsync(()->check(p,p.rpg.runtime.platformTransactionsAllowed()&&p.jobsAllowed(),"committed_configuration_reopens_shared_admission"),p.owner).thenComposeAsync(v->p.archiveConfig(plan.id()),p.owner);},p.owner);}
 private static CompletionStage<Void> readLoad(PlatformRuntime p){long start=System.nanoTime();int tick=Bukkit.getCurrentTick();var times=new ArrayList<Long>();CompletionStage<Void> chain=CompletableFuture.completedFuture(null);for(int b=0;b<4;b++)chain=chain.thenComposeAsync(v->{var batch=new ArrayList<CompletableFuture<?>>();for(int i=0;i<8;i++){long at=System.nanoTime();batch.add(p.reviewConfig().thenAcceptAsync(r->times.add(System.nanoTime()-at),p.owner).toCompletableFuture());}return CompletableFuture.allOf(batch.toArray(CompletableFuture[]::new));},p.owner);return chain.thenRunAsync(()->{Collections.sort(times);check(p,times.size()==32,"concurrent_read_only_reviews_complete_off_main_file_worker");p.plugin.getLogger().info("HEARTH_OPERATIONS_LOAD reviews=32 elapsed_ms="+(System.nanoTime()-start)/1_000_000+" p95_us="+times.get(30)/1000+" ticks="+(Bukkit.getCurrentTick()-tick)+" mspt="+Bukkit.getAverageTickTime());},p.owner);}
 private static CompletionStage<Void> preserved(PlatformRuntime p,Properties values){var economy=p.rpg.runtime.economy();return economy.store.account(economy.store.context(economy.settings.realm(),UUID.fromString(values.getProperty("actor")))).thenAcceptAsync(a->check(p,EnchantStore.hash(a.inventory().payload()).equals(values.getProperty("upgrade-hash")),"upgrade_inventory_is_preserved"),p.owner).thenCompose(v->economy.store.account(economy.store.context(economy.settings.realm(),UUID.fromString(values.getProperty("sale"))))).thenAcceptAsync(a->check(p,a.balance()==Long.parseLong(values.getProperty("balance"))&&EnchantStore.hash(a.inventory().payload()).equals(values.getProperty("sale-hash")),"sale_balance_and_items_are_preserved"),p.owner);}
}
